const s = $('Settings').first().json;
const DAY = 86400000;
const today = new Date(); today.setHours(0, 0, 0, 0);
const weekAgo = today.getTime() - 6 * DAY;
const toDate = (v) => { if (v === '' || v === null || v === undefined) return null; const d = typeof v === 'number' ? new Date(Math.round((v - 25569) * DAY)) : new Date(String(v).trim()); return isNaN(d) ? null : d; };
const esc = (x) => String(x || '').replace(/&/g, '&amp;').replace(/</g, '&lt;');
const f = String(s.clientFilter || '').trim().toLowerCase();
const tasks = $input.all().map(i => i.json).filter(t => t.Task && (!f || String(t.Client || '').toLowerCase() === f));
const st = (t) => String(t.Status || '').trim().toLowerCase();
const done = tasks.filter(t => st(t) === 'done' && toDate(t['Completed On']) && toDate(t['Completed On']).getTime() >= weekAgo);
const prog = tasks.filter(t => st(t) === 'in progress');
const blocked = tasks.filter(t => st(t) === 'blocked');
const li = (t, extra) => `<li>${esc(t.Task)}${extra ? ' <span style="color:#666">' + extra + '</span>' : ''}</li>`;
const sec = (title, arr, fn) => `<h3 style="margin:18px 0 6px;font-size:15px">${title} (${arr.length})</h3>` + (arr.length ? `<ul>${arr.map(fn).join('')}</ul>` : '<p style="color:#666">None.</p>');
const html = `<p>Hi,</p><p>Here is this week's update for <b>${esc(s.clientName)}</b>.</p>` +
  sec('Done this week', done, t => li(t)) +
  sec('In progress', prog, t => { const d = toDate(t.Due); return li(t, d ? (d < today ? '<b style="color:#c0392b">overdue, was due ' + d.toISOString().slice(0,10) + '</b>' : 'due ' + d.toISOString().slice(0,10)) : ''); }) +
  sec('Blocked / waiting on you', blocked, t => li(t, esc(t.Notes))) +
  `<p>Reply to this email if priorities have changed.</p><p>${esc(s.yourName)}</p>`;
return [{ json: { to: s.recipients, subject: `Weekly update: ${s.clientName} (${done.length} done, ${blocked.length} waiting on you)`, html } }];
